python3 - <<'EOF'
import json, sys

with open("BellevueWeather/BellevueWeather/BellevueWeather.flow") as f:
    flow = json.load(f)

node_ids = {n["id"] for n in flow["nodes"]}
print("Nodes:", sorted(node_ids))

errors = []

# Check every edge references valid node ids
for edge in flow["edges"]:
    if edge["sourceNodeId"] not in node_ids:
        errors.append(f"Edge {edge['id']}: sourceNodeId '{edge['sourceNodeId']}' not in nodes")
    if edge["targetNodeId"] not in node_ids:
        errors.append(f"Edge {edge['id']}: targetNodeId '{edge['targetNodeId']}' not in nodes")

# Check no stale variable bindings reference old node ids
for var in flow.get("variables", {}).get("nodes", []):
    bid = var.get("binding", {}).get("nodeId")
    if bid and bid not in node_ids:
        errors.append(f"Variable '{var['id']}': references removed node '{bid}'")

# Check layout keys are all valid node ids
for nid in flow.get("layout", {}).get("nodes", {}):
    if nid not in node_ids:
        errors.append(f"Layout references removed node '{nid}'")

# Check decision expression no longer references formatSummary
for n in flow["nodes"]:
    if n["id"] == "checkTemperature":
        expr = n["inputs"].get("expression", "")
        if "formatSummary" in expr:
            errors.append("checkTemperature expression still references formatSummary")
        print(f"Decision expression: {expr}")

# Check formatSummary script references checkTemperature
for n in flow["nodes"]:
    if n["id"] == "formatSummary":
        script = n["inputs"].get("script", "")
        if "checkTemperature" not in script:
            errors.append("formatSummary script does not reference checkTemperature")
        print(f"formatSummary script:\n{script}")

# Check edges: both true & false from checkTemperature go to formatSummary
check_edges = [(e["sourcePort"], e["targetNodeId"]) for e in flow["edges"] if e["sourceNodeId"] == "checkTemperature"]
print(f"checkTemperature outgoing edges: {check_edges}")
if set(check_edges) != {("true", "formatSummary"), ("false", "formatSummary")}:
    errors.append(f"checkTemperature branches don't both go to formatSummary: {check_edges}")

# Check formatSummary leads to end
fmt_edges = [(e["sourcePort"], e["targetNodeId"]) for e in flow["edges"] if e["sourceNodeId"] == "formatSummary"]
print(f"formatSummary outgoing edges: {fmt_edges}")
if fmt_edges != [("success", "end")]:
    errors.append(f"formatSummary doesn't go to 'end': {fmt_edges}")

# Check only one end node
end_nodes = [n for n in flow["nodes"] if n["type"] == "core.control.end"]
print(f"End nodes: {[n['id'] for n in end_nodes]}")
if len(end_nodes) != 1:
    errors.append(f"Expected 1 end node, got {len(end_nodes)}")

if errors:
    print("\nVALIDATION ERRORS:")
    for e in errors:
        print(" -", e)
    sys.exit(1)
else:
    print("\nAll validation checks passed!")
EOF

